import {ACCESS_MODULES,STAFF_ROLES,presetPermissions,staffPermissions,editPermission,can} from './access-policy.js';
import {escapeHTML as e,icon,dateTimeLabel} from './visuals.js';

const input=(name,label,type='text',value='',extra='')=>`<div class="field"><label for="staff-${name}">${label}</label><input id="staff-${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`;
const nameInput=(value='')=>input('name','Họ và tên','text',value,'required minlength="2" maxlength="80" autocomplete="name"');
const usernameInput=(value='')=>input('username','Tên đăng nhập','text',value,'required minlength="3" maxlength="32" autocomplete="username" autocapitalize="none" spellcheck="false" pattern="[a-zA-Z0-9][a-zA-Z0-9._\\-]{2,31}"');
const passwordInput=(label='Mật khẩu',name='password',required=true)=>input(name,label,'password','',`${required?'required':''} minlength="8" maxlength="128" autocomplete="${name==='currentPassword'?'current-password':'new-password'}"`);

export function staffGate(setup){
  return `<section class="staff-gate"><div class="staff-gate-intro"><span class="eyebrow">KHU VỰC NHÂN VIÊN</span><h1 class="serif">${setup?'Bắt đầu quản lý.':'Chào bạn trở lại.'}</h1><p>${setup?'Tạo quản trị viên đầu tiên để quản lý chiến dịch và cấp quyền cho từng nhân viên.':'Đăng nhập để xem voucher và các chức năng được cấp cho bạn.'}</p><div class="staff-gate-points"><span>${icon('ticket')} Tra cứu voucher nhanh</span><span>${icon('check')} Rõ người xác nhận sử dụng</span><span>${icon('lock')} Mỗi nhân viên, một tài khoản</span></div></div><div class="panel staff-login-card"><div class="modal-symbol">${icon('lock')}</div><h2>${setup?'Tạo quản trị viên':'Đăng nhập nhân viên'}</h2><form data-form="${setup?'staff-setup':'staff-login'}">${setup?nameInput():''}${usernameInput()}${setup?passwordInput():input('password','Mật khẩu','password','','required maxlength="128" autocomplete="current-password"')}${setup?passwordInput('Nhập lại mật khẩu','passwordConfirm'):''}<p class="inline-error" data-error role="alert"></p><button class="btn full" type="submit">${setup?'Tạo tài khoản & tiếp tục':'Đăng nhập'} ${icon('arrow')}</button></form><p class="hint">${setup?'Dữ liệu game đang có sẽ được giữ nguyên.':'Quên mật khẩu? Nhờ quản trị viên đặt lại cho bạn.'}</p><div class="notice">${icon('info')}<span>Bản thử nghiệm trên trình duyệt này. Tài khoản và quyền chưa được bảo vệ bằng máy chủ, chưa đồng bộ sang thiết bị khác. Hãy dùng mật khẩu riêng cho bản thử nghiệm.</span></div></div></section>`;
}
export function permissionFields(role,permissions=presetPermissions(role)){
  return `<div class="permission-table"><div class="permission-table-heading"><strong>Chức năng được truy cập</strong><span>Mức quyền</span></div>${ACCESS_MODULES.map(m=>{
    const level=permissions.includes(editPermission(m.id))?'edit':permissions.includes(m.id+'.view')?'view':'none';
    return `<div class="permission-row"><label for="permission-${m.id}">${icon(m.icon)}${m.label}</label><select id="permission-${m.id}" name="permission-${m.id}" aria-label="Quyền ${m.label}" ${role==='admin'?'disabled':''}><option value="none" ${level==='none'?'selected':''}>Không truy cập</option><option value="view" ${level==='view'?'selected':''}>Chỉ xem</option>${m.edit?`<option value="edit" ${level==='edit'?'selected':''}>${m.edit==='Chỉnh sửa'?'Xem & chỉnh sửa':'Xem & '+m.edit.toLowerCase()}</option>`:''}</select></div>`;
  }).join('')}</div><p class="hint">${role==='admin'?'Quản trị viên có toàn quyền, gồm quản lý tài khoản và khôi phục dữ liệu game.':'Nhóm mẫu chỉ mở Voucher. Anh có thể cấp thêm quyền bên trên. Quyền chỉnh sửa luôn bao gồm xem; quản lý nhân viên chỉ dành cho quản trị viên.'}</p>`;
}
export function staffEditForm(staff){
  const role=staff?.role||'viewer';
  return `<h2 class="serif">${staff?'Chỉnh tài khoản':'Thêm nhân viên'}</h2><p class="intro">Mỗi người một tài khoản để theo dõi đúng người xác nhận voucher.</p><form data-form="staff-save"><input type="hidden" name="id" value="${e(staff?.id||'')}"><input type="hidden" name="revision" value="${staff?.sessionVersion||0}"><div class="fields">${nameInput(staff?.name)}${usernameInput(staff?.username)}${passwordInput(staff?'Mật khẩu mới (để trống nếu giữ nguyên)':'Mật khẩu','password',!staff)}${passwordInput('Nhập lại mật khẩu mới','passwordConfirm',!staff)}</div><div class="field"><label for="staff-role">Nhóm quyền mẫu</label><select id="staff-role" name="role">${Object.entries(STAFF_ROLES).map(([id,label])=>`<option value="${id}" ${id===role?'selected':''}>${label}</option>`).join('')}</select></div><div id="staff-permissions">${permissionFields(role,staff?staffPermissions(staff):presetPermissions(role))}</div><label class="check-field"><input type="checkbox" name="active" ${staff?.active===false?'':'checked'}>Cho phép tài khoản đăng nhập</label>${staff?'<p class="hint">Lưu thay đổi sẽ kết thúc các phiên đăng nhập của tài khoản này. Nhân viên cần đăng nhập lại để dùng quyền mới.</p>':''}<p class="inline-error" data-error role="alert"></p><div class="form-actions"><button class="btn secondary" type="button" data-action="close">Hủy</button><button class="btn" type="submit">${icon('check')}Lưu tài khoản</button></div></form>`;
}
export function staffManager(staffList,state,tab='people'){
  const active=staffList.filter(s=>s.active).length;
  const rows=staffList.map(s=>{
    const custom=s.role!=='admin'&&JSON.stringify([...staffPermissions(s)].sort())!==JSON.stringify(presetPermissions(s.role).sort());
    return `<tr><td><div class="staff-person">${icon('user')}<div><strong>${e(s.name)}</strong><small>@${e(s.username)}</small></div></div></td><td>${STAFF_ROLES[s.role]}${custom?'<small class="redemption-meta">Quyền tùy chỉnh</small>':''}</td><td><span class="badge ${s.active?'':'gray'}">${s.active?'Đang hoạt động':'Đã khóa'}</span></td><td>${s.lastLoginAt?dateTimeLabel(s.lastLoginAt):'Chưa đăng nhập'}</td><td><button class="btn small secondary" data-action="staff-edit" data-id="${e(s.id)}">${icon('edit')}Chỉnh sửa</button></td></tr>`;
  }).join('');
  const labels={setup:'Tạo quản trị viên đầu tiên',create:'Tạo tài khoản',update:'Cập nhật tài khoản / quyền',password:'Đổi mật khẩu',reset:'Khôi phục dữ liệu mẫu'};
  const events=[...(state.staffAudit||[]).map(a=>({...a,label:labels[a.action]||'Cập nhật tài khoản'})),...state.redemptions.filter(r=>r.actorType!=='customer').map(r=>({...r,label:'Xác nhận sử dụng voucher',actorName:r.actorName||r.employee||'Nhân viên',targetName:state.vouchers.find(v=>v.id===r.voucherId)?.code||r.voucherId,detail:r.branch}))].sort((a,b)=>b.at.localeCompare(a.at)).slice(0,100);
  return `<div class="admin-heading"><div><div class="eyebrow">TÀI KHOẢN & QUYỀN TRUY CẬP</div><h1 class="serif">Nhân viên & phân quyền</h1><p>Cấp đúng quyền, rõ người thao tác.</p></div><button class="btn" data-action="staff-add">${icon('plus')}Thêm nhân viên</button></div><div class="staff-summary"><div>${icon('user')}<span><strong>${staffList.length}</strong> tài khoản</span></div><div>${icon('check')}<span><strong>${active}</strong> đang hoạt động</span></div><div>${icon('lock')}<span><strong>${staffList.length-active}</strong> đã khóa</span></div></div><div class="tabs" role="group" aria-label="Quản lý nhân viên"><button class="${tab==='people'?'selected':''}" data-action="staff-tab" data-value="people">Tài khoản nhân viên</button><button class="${tab==='audit'?'selected':''}" data-action="staff-tab" data-value="audit">Nhật ký thao tác</button></div>${tab==='people'?`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Nhân viên</th><th>Nhóm quyền</th><th>Trạng thái</th><th>Đăng nhập gần nhất</th><th></th></tr></thead><tbody>${rows}</tbody></table></div></section><div class="staff-role-guide"><article>${icon('ticket')}<h3>Chỉ xem voucher</h3><p>Tra cứu và xem chi tiết. Không thay đổi trạng thái quà.</p></article><article>${icon('store')}<h3>Thu ngân</h3><p>Xem voucher và xác nhận sử dụng một lần tại quầy.</p></article><article>${icon('settings')}<h3>Quản trị viên</h3><p>Quản lý chiến dịch, nội dung và quyền của nhân viên.</p></article></div>`:`<section class="panel"><div class="panel-title"><h2>Lịch sử gần nhất</h2><small>Tối đa 100 sự kiện hiển thị</small></div>${events.length?`<div class="table-wrap"><table><thead><tr><th>Thời gian</th><th>Người thao tác</th><th>Hành động</th><th>Tài khoản / voucher</th></tr></thead><tbody>${events.map(a=>`<tr><td>${dateTimeLabel(a.at)}</td><td>${e(a.actorName)}</td><td>${e(a.label)}${a.detail?`<small class="redemption-meta">${e(a.detail)}</small>`:''}</td><td>${e(a.targetName)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="hint">Chưa có thao tác được ghi nhận.</p>'}</section>`}`;
}
export function staffAccount(staff){
  return `<div class="modal-symbol">${icon('user')}</div><h2 class="serif">${e(staff.name)}</h2><p class="intro">@${e(staff.username)} · ${STAFF_ROLES[staff.role]}</p><form data-form="staff-password">${passwordInput('Mật khẩu hiện tại','currentPassword')}${passwordInput('Mật khẩu mới')}${passwordInput('Nhập lại mật khẩu mới','passwordConfirm')}<p class="inline-error" data-error role="alert"></p><button class="btn full" type="submit">Đổi mật khẩu</button><p class="hint">Sau khi đổi mật khẩu, hãy đăng nhập lại trên các tab đang sử dụng.</p></form><button class="text-button staff-signout" data-action="staff-logout">${icon('logout')}Đăng xuất nhân viên</button>`;
}
